package nl.codex.kpndenon;

import android.app.Activity;
import android.os.Bundle;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import android.content.Context;
import android.net.wifi.WifiManager;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private android.content.SharedPreferences prefs;
    private TextView status;
    private LinearLayout root;
    private static final int BG=Color.rgb(11,16,27), PANEL=Color.rgb(24,32,48), MUTED=Color.rgb(158,174,194), ACCENT=Color.rgb(255,126,74);
    private static final String[][] SOURCES={{"KPN TV","SAT/CBL","1"},{"Nintendo Switch","GAME","4"},{"Android TV-box","BD","3"},{"DVD","DVD","2"},{"Media Player","MPLAY","5"},{"AUX 1","AUX1","Front"},{"AUX 2","AUX2","6"},{"CD","CD","Geen"}};
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setBackgroundColor(BG);prefs=getSharedPreferences("setup",MODE_PRIVATE);renderHome();if(prefs.getString("ip","").isEmpty())discover(false);}
    private void renderHome(){
        root=base(); ScrollView scroll=new ScrollView(this); LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(38,24,38,24);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,-1));
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView title=text("DENON",29,true);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));head.addView(action("⚙  Instellingen",()->renderSettings()));body.addView(head);
        TextView subtitle=text("AVR-X2400H  ·  HDMI-bron kiezen",16,false);subtitle.setTextColor(MUTED);body.addView(subtitle);
        ArrayList<Integer> ids=new ArrayList<>();for(int i=0;i<SOURCES.length;i++)if(prefs.getBoolean("visible_"+SOURCES[i][1],true))ids.add(i);Collections.sort(ids,(a,b)->Integer.compare(prefs.getInt("order_"+SOURCES[a][1],a),prefs.getInt("order_"+SOURCES[b][1],b)));
        View firstCard=null;for(int i=0;i<ids.size();i+=3){LinearLayout row=new LinearLayout(this);for(int k=i;k<Math.min(i+3,ids.size());k++){int n=ids.get(k);String[] s=SOURCES[n];String key=s[1],label=prefs.getString("label_"+key,s[0]),port=prefs.getString("port_"+key,s[2]);LinearLayout card=panel();card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(24,24,20,24);LinearLayout meta=new LinearLayout(this);meta.setGravity(Gravity.CENTER_VERTICAL);TextView icon=text(prefs.getString("icon_"+key,defaultIcon(key)),28,true);meta.addView(icon);TextView hdmi=text("HDMI  "+port.toUpperCase(Locale.ROOT),12,true);hdmi.setIncludeFontPadding(true);hdmi.setTextColor(ACCENT);LinearLayout.LayoutParams hl=new LinearLayout.LayoutParams(-2,-2);hl.leftMargin=14;meta.addView(hdmi,hl);card.addView(meta);TextView name=text(label,18,true);name.setIncludeFontPadding(true);name.setMinHeight(56);name.setGravity(Gravity.CENTER_VERTICAL);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(name);card.setFocusable(true);card.setClickable(true);setFocusFeedback(card);if(firstCard==null)firstCard=card;card.setOnClickListener(v->chooseSource(key,label));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,144,1);lp.setMargins(0,16,16,0);row.addView(card,lp);}body.addView(row);}if(firstCard!=null){View focusTarget=firstCard;root.post(()->focusTarget.requestFocus());}
        LinearLayout footer=new LinearLayout(this);footer.setGravity(Gravity.CENTER_VERTICAL);status=text("Selecteer een bron. De receiver wordt ingeschakeld en naar de gekozen ingang geschakeld.",14,false);status.setTextColor(MUTED);footer.addView(status,new LinearLayout.LayoutParams(0,-2,1));TextView ipStatus=text(prefs.getString("ip","Geen receiver"),12,false);ipStatus.setTextColor(MUTED);ipStatus.setGravity(Gravity.RIGHT);footer.addView(ipStatus);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=18;body.addView(footer,sp);
    }
    private void renderSettings(){
        root=base();ScrollView sc=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(38,20,38,24);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,-1));
        LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER);TextView settingsTitle=text("Instellingen",28,true);settingsTitle.setGravity(Gravity.CENTER);top.addView(settingsTitle);body.addView(top);LinearLayout readyRow=new LinearLayout(this);readyRow.setGravity(Gravity.CENTER);readyRow.addView(action("Klaar",()->renderHome()));LinearLayout.LayoutParams readyLp=new LinearLayout.LayoutParams(-1,-2);readyLp.topMargin=6;readyLp.bottomMargin=12;body.addView(readyRow,readyLp);
        body.addView(text("Receiver zoeken",17,true));TextView ip=text("IP-adres: "+(prefs.getString("ip","").isEmpty()?"niet gevonden":prefs.getString("ip","")),14,false);ip.setTextColor(MUTED);body.addView(ip);
        LinearLayout findRow=new LinearLayout(this);Button find=action("⌕  Zoek Denon automatisch",()->{ip.setText("Zoeken via netwerkontdekking…");discover(true);});findRow.addView(find);EditText manual=new EditText(this);manual.setSingleLine(true);manual.setTextColor(Color.WHITE);manual.setHintTextColor(MUTED);manual.setHint("of vul IP in");manual.setText(prefs.getString("ip",""));manual.setPadding(12,0,12,0);manual.setBackground(bg(PANEL,14));LinearLayout.LayoutParams ml=new LinearLayout.LayoutParams(220,52);ml.leftMargin=12;findRow.addView(manual,ml);Button saveIp=action("Opslaan",()->{prefs.edit().putString("ip",manual.getText().toString().trim()).apply();ip.setText("IP-adres: "+prefs.getString("ip",""));});LinearLayout.LayoutParams sil=new LinearLayout.LayoutParams(-2,52);sil.leftMargin=8;findRow.addView(saveIp,sil);body.addView(findRow);
        TextView help=text("Namen, HDMI-aansluiting en volgorde zijn instelbaar. Verander een HDMI-nummer als de ingangen op je receiver anders zijn toegewezen.",14,false);help.setTextColor(MUTED);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=14;body.addView(help,hp);
        for(int i=0;i<SOURCES.length;i++){String[] s=SOURCES[i];String key=s[1];LinearLayout card=panel();card.setOrientation(LinearLayout.VERTICAL);card.setPadding(16,10,16,10);LinearLayout first=new LinearLayout(this);first.setGravity(Gravity.CENTER_VERTICAL);TextView original=text(s[0]+"  ·  "+key,14,true);original.setTextColor(ACCENT);first.addView(original,new LinearLayout.LayoutParams(0,-2,1));Switch visible=new Switch(this);visible.setTag("visible_"+key);visible.setText("Tonen");visible.setTextColor(Color.WHITE);visible.setTextSize(13);visible.setMinHeight(58);visible.setChecked(prefs.getBoolean("visible_"+key,true));first.addView(visible);Button up=small("▲",()->move(key,-1));Button down=small("▼",()->move(key,1));first.addView(up);first.addView(down);card.addView(first);
            LinearLayout fields=new LinearLayout(this);fields.setGravity(Gravity.CENTER_VERTICAL);EditText icon=new EditText(this);icon.setTag("icon_"+key);icon.setSingleLine(true);icon.setTextSize(22);icon.setTextColor(Color.WHITE);icon.setHintTextColor(MUTED);icon.setHint("◉");icon.setText(prefs.getString("icon_"+key,defaultIcon(key)));icon.setGravity(Gravity.CENTER);icon.setPadding(4,0,4,0);icon.setBackground(bg(BG,10));LinearLayout.LayoutParams il=new LinearLayout.LayoutParams(76,54);il.rightMargin=10;fields.addView(icon,il);EditText label=new EditText(this);label.setTag("label_"+key);label.setSingleLine(true);label.setTextSize(16);label.setTextColor(Color.WHITE);label.setHintTextColor(MUTED);label.setHint("Naam in app");label.setText(prefs.getString("label_"+key,s[0]));label.setPadding(12,0,12,0);label.setBackground(bg(BG,10));fields.addView(label,new LinearLayout.LayoutParams(0,54,1));EditText port=new EditText(this);port.setTag("port_"+key);port.setSingleLine(true);port.setTextSize(15);port.setTextColor(Color.WHITE);port.setHintTextColor(MUTED);port.setHint("HDMI");port.setText(prefs.getString("port_"+key,s[2]));port.setGravity(Gravity.CENTER);port.setPadding(6,0,6,0);port.setBackground(bg(BG,10));LinearLayout.LayoutParams pl=new LinearLayout.LayoutParams(124,54);pl.leftMargin=12;fields.addView(port,pl);card.addView(fields);LinearLayout.LayoutParams cl=new LinearLayout.LayoutParams(-1,-2);cl.topMargin=10;body.addView(card,cl);}
        Button save=action("Opslaan en terug",()->{android.content.SharedPreferences.Editor e=prefs.edit();e.putString("ip",manual.getText().toString().trim());for(String[] s:SOURCES){String key=s[1];EditText l=root.findViewWithTag("label_"+key),p=root.findViewWithTag("port_"+key),ic=root.findViewWithTag("icon_"+key);Switch v=root.findViewWithTag("visible_"+key);if(l!=null&&!l.getText().toString().trim().isEmpty())e.putString("label_"+key,l.getText().toString().trim());if(p!=null)e.putString("port_"+key,p.getText().toString().trim());if(ic!=null&&!ic.getText().toString().trim().isEmpty())e.putString("icon_"+key,ic.getText().toString().trim());if(v!=null)e.putBoolean("visible_"+key,v.isChecked());}e.apply();renderHome();});LinearLayout.LayoutParams sv=new LinearLayout.LayoutParams(-2,100);sv.gravity=Gravity.CENTER_HORIZONTAL;sv.topMargin=20;sv.bottomMargin=20;body.addView(save,sv);
    }
    private void move(String key,int delta){int cur=prefs.getInt("order_"+key,index(key));ArrayList<Integer> order=new ArrayList<>();for(String[] s:SOURCES)order.add(prefs.getInt("order_"+s[1],index(s[1])));int pos=order.indexOf(cur),next=Math.max(0,Math.min(order.size()-1,pos+delta));if(pos<0)return;int other=order.get(next);prefs.edit().putInt("order_"+key,other).putInt("order_"+SOURCES[indexByOrder(other)][1],cur).apply();renderSettings();}
    private int index(String key){for(int i=0;i<SOURCES.length;i++)if(SOURCES[i][1].equals(key))return i;return 0;}private int indexByOrder(int value){for(int i=0;i<SOURCES.length;i++)if(prefs.getInt("order_"+SOURCES[i][1],i)==value)return i;return Math.max(0,Math.min(SOURCES.length-1,value));}
    private String defaultIcon(String key){switch(key){case "SAT/CBL":return "📺";case "GAME":return "🎮";case "BD":return "📀";case "DVD":return "💿";case "MPLAY":return "▶️";case "AUX1":case "AUX2":return "🔌";case "CD":return "🎵";default:return "◉";}}
    private void discover(boolean update){WifiManager wm=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);WifiManager.MulticastLock lock=wm.createMulticastLock("denon-ssdp");worker.execute(()->{String found=null;try{lock.acquire();try(DatagramSocket sock=new DatagramSocket()){sock.setSoTimeout(450);sock.setBroadcast(true);byte[] q=("M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 2\r\nST: ssdp:all\r\n\r\n").getBytes("US-ASCII");InetAddress multicast=InetAddress.getByName("239.255.255.250");for(int t=0;t<3;t++)sock.send(new DatagramPacket(q,q.length,multicast,1900));long end=System.currentTimeMillis()+3500;while(System.currentTimeMillis()<end){try{byte[] b=new byte[4096];DatagramPacket p=new DatagramPacket(b,b.length);sock.receive(p);String r=new String(p.getData(),0,p.getLength(),"US-ASCII");String loc=header(r,"LOCATION");if(loc!=null){String host=new URL(loc).getHost();if(host.equals(p.getAddress().getHostAddress())){if(found==null)found=host; if(r.toLowerCase(Locale.ROOT).contains("denon")){found=host;break;}}}}catch(SocketTimeoutException e){}}} }catch(Exception ignored){}finally{if(lock.isHeld())lock.release();}final String result=found;runOnUiThread(()->{if(isFinishing())return;if(result!=null){prefs.edit().putString("ip",result).apply();if(update){renderSettings();Toast.makeText(this,"Denon gevonden: "+result,Toast.LENGTH_SHORT).show();}else renderHome();}else if(update){ipToast("Geen Denon via SSDP gevonden. Vul het IP-adres handmatig in.");}});});}
    private String header(String response,String name){for(String line:response.split("\\r?\\n"))if(line.toLowerCase(Locale.ROOT).startsWith(name.toLowerCase(Locale.ROOT)+":"))return line.substring(name.length()+1).trim();return null;}
    private void ipToast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    private void chooseSource(String command,String label){String ip=prefs.getString("ip","").trim();if(ip.isEmpty()){status.setText("Nog geen receiver gevonden. Open Instellingen en kies ‘Zoek Denon automatisch’.");return;}status.setText("Receiver inschakelen en schakelen naar "+label+"…");worker.execute(()->{String result;try(Socket socket=new Socket()){socket.connect(new InetSocketAddress(ip,23),3000);socket.setSoTimeout(2500);OutputStream out=socket.getOutputStream();out.write("PWON\r".getBytes("US-ASCII"));out.flush();Thread.sleep(180);out.write(("SI"+command+"\r").getBytes("US-ASCII"));out.flush();result="Denon ingeschakeld · "+label;}catch(Exception e){result="Geen Telnet-verbinding met de Denon. Controleer netwerk en IP.";}String msg=result;runOnUiThread(()->{if(status!=null)status.setText(msg);});});}
    private LinearLayout base(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setBackgroundColor(BG);setContentView(l);return l;}
    private LinearLayout panel(){LinearLayout l=new LinearLayout(this);l.setBackground(bg(PANEL,16));return l;}
    private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);d.setStroke(1,Color.rgb(43,56,75));return d;}
    private TextView text(String v,int size,boolean bold){TextView t=new TextView(this);t.setText(v);t.setTextSize(size);t.setTextColor(Color.WHITE);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,5,0,5);return t;}
    private void setFocusFeedback(View v){v.setOnFocusChangeListener((view,focused)->{GradientDrawable d=bg(focused?Color.rgb(48,40,47):PANEL,16);if(focused)d.setStroke(3,ACCENT);view.setBackground(d);});}
    private Button action(String label,Runnable click){Button b=new Button(this);b.setText(label);b.setTextColor(Color.WHITE);b.setTextSize(17);b.setAllCaps(false);b.setPadding(22,12,22,12);b.setMinHeight(68);b.setBackground(bg(PANEL,12));b.setFocusable(true);b.setOnFocusChangeListener((view,focused)->{GradientDrawable d=bg(focused?Color.rgb(48,40,47):PANEL,12);if(focused)d.setStroke(3,ACCENT);view.setBackground(d);view.setScaleX(focused?1.03f:1f);view.setScaleY(focused?1.03f:1f);});b.setOnClickListener(v->click.run());return b;}
    private Button small(String label,Runnable click){Button b=action(label,click);b.setTextSize(16);b.setMinWidth(64);b.setMinimumWidth(64);b.setMinHeight(60);return b;}
    @Override public void onBackPressed(){renderHome();}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
